const request = $json || {};
const expected = 'REPLACE_WITH_EVIDENCE_GATEWAY_TOKEN';
const received = String(request.headers?.authorization || request.headers?.Authorization || '').replace(/^Bearer\s+/i, '').trim();
const tokenEquals = (left, right) => { if (!left || left.length !== right.length) return false; let diff = 0; for (let index = 0; index < left.length; index += 1) diff |= left.charCodeAt(index) ^ right.charCodeAt(index); return diff === 0; };
if (!tokenEquals(received, expected)) return [{ json: { valid: false, status: 'unauthorized', errors: ['Unauthorized evidence gateway request.'] } }];
const raw = request.body ?? request;
const allowedFields = new Set(['countryCode', 'table', 'producerFiles', 'sourceSql', 'anomalyDate']);
const aliases = { id: 'ine', indonesia: 'ine', cn: 'cn', china: 'cn', ph: 'ph', philippines: 'ph', th: 'th', thailand: 'th', pk: 'pk', pakistan: 'pk', mx: 'mx', mexico: 'mx' };
const errors = [];
const isObject = raw && typeof raw === 'object' && !Array.isArray(raw);
if (!isObject) errors.push('Request body must be a JSON object.');
if (isObject && Object.keys(raw).some((key) => !allowedFields.has(key))) errors.push('Only countryCode, table, producerFiles, sourceSql, and anomalyDate are accepted.');
const isString = (value) => typeof value === 'string';
if (!isString(raw?.countryCode)) errors.push('countryCode must be a scalar string.');
if (!isString(raw?.table)) errors.push('table must be a scalar string.');
if (!isString(raw?.anomalyDate)) errors.push('anomalyDate must be a scalar string.');
if (raw?.sourceSql !== undefined && !isString(raw.sourceSql)) errors.push('sourceSql must be a scalar string when supplied.');
const countryCode = isString(raw?.countryCode) ? aliases[raw.countryCode.trim().toLowerCase()] : undefined;
const table = isString(raw?.table) ? raw.table.trim().toLowerCase() : '';
const anomalyDate = isString(raw?.anomalyDate) ? raw.anomalyDate.trim() : '';
const producerFiles = raw?.producerFiles === undefined ? [] : raw.producerFiles;
const sourceSql = isString(raw?.sourceSql) ? raw.sourceSql : '';
if (!countryCode) errors.push('Unsupported countryCode; use cn, ine/id, ph, th, pk, or mx.');
if (!/^[a-z][a-z0-9_]{0,127}\.[a-z][a-z0-9_]{0,127}$/.test(table)) errors.push('table must be a lowercase schema.table identifier.');
const parseDate = (value) => { if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null; const date = new Date(value + 'T00:00:00Z'); return Number.isNaN(date.valueOf()) || date.toISOString().slice(0, 10) !== value ? null : date; };
if (!parseDate(anomalyDate)) errors.push('anomalyDate must be a real YYYY-MM-DD date.');
if (!Array.isArray(producerFiles) || producerFiles.length > 20 || producerFiles.some((file) => typeof file !== 'string' || file.length < 1 || file.length > 500 || file.startsWith('/') || !/^[A-Za-z0-9_./-]+$/.test(file) || file.includes('..'))) errors.push('producerFiles must contain at most 20 safe relative paths, each no longer than 500 characters.');
if (sourceSql.length > 20000) errors.push('sourceSql must not exceed 20000 characters.');
if (!producerFiles.length && !sourceSql.trim()) errors.push('At least one producerFiles entry or sourceSql is required as evidence.');
if (errors.length) return [{ json: { valid: false, status: 'invalid_request', errors } }];
return [{ json: { valid: true, countryCode, table, producerFiles, sourceSql, anomalyDate } }];

// Deployment-controlled reference only: no request field can select a workflow, endpoint, credential, or execution option.
const dsRuntimeReference = { workflowId: 'REPLACE_WITH_DS_TASK_MATCH_CANDIDATE_QUERY_WORKFLOW_ID', workflowName: 'DS任务匹配候选查询_execute_workflow', verified: false };
if (!dsRuntimeReference.verified || dsRuntimeReference.workflowId.startsWith('REPLACE_WITH_')) return [{ json: { ...$json, status: 'unavailable', reason: 'no_verified_ds_reference', candidates: [] } }];
return [{ json: { ...$json, dsRuntimeReference }];

const source = $('Validate DS Runtime Evidence Input').first().json;
const rows = $input.all().flatMap((item) => Array.isArray(item.json?.candidates) ? item.json.candidates : []);
const candidates = rows.filter((candidate) => { const confidence = candidate?.confidence; return confidence === 'high' || (typeof confidence === 'number' && Number.isFinite(confidence) && confidence >= 0.9); }).map((candidate) => ({ workflowName: String(candidate.workflowName || candidate.name || '').slice(0, 300), projectName: candidate.projectName ? String(candidate.projectName).slice(0, 300) : undefined, confidence: candidate.confidence, matchReasons: Array.isArray(candidate.matchReasons) ? candidate.matchReasons.slice(0, 10).map((reason) => String(reason).slice(0, 300)) : [] })).filter((candidate) => candidate.workflowName);
return [{ json: { status: 'ok', countryCode: source.countryCode, table: source.table, anomalyDate: source.anomalyDate, candidates } }];
